#pragma once
#include "PresetLibrary.h"
class PresetBrowser:public juce::Component,private juce::ListBoxModel {
public:
 PresetBrowser(PlateProcessor&processor,std::function<void()> changed):p(processor),onChange(std::move(changed)){
  dark.setColour(juce::TextButton::buttonColourId,juce::Colour(0xff252525));dark.setColour(juce::TextButton::buttonOnColourId,juce::Colour(0xff655b35));dark.setColour(juce::TextButton::textColourOffId,juce::Colour(0xffdddddd));dark.setColour(juce::TextButton::textColourOnId,juce::Colours::white);dark.setColour(juce::ComboBox::backgroundColourId,juce::Colour(0xff171717));dark.setColour(juce::ComboBox::textColourId,juce::Colour(0xffdddddd));setLookAndFeel(&dark);
  search.setName("preset-search");name.setName("preset-name");list.setName("preset-list");addAndMakeVisible(search);search.setTextToShowWhenEmpty("Search presets...",juce::Colour(0xff888888));search.onTextChange=[this]{refresh();};
  addAndMakeVisible(category);category.addItem("All categories",1);juce::StringArray cats;for(auto&e:library.entries)cats.addIfNotAlreadyThere(e.category);cats.addIfNotAlreadyThere("User");for(int i=0;i<cats.size();++i)category.addItem(cats[i],i+2);category.setSelectedId(1,juce::dontSendNotification);category.onChange=[this]{refresh();};
  const char*names[]={"Short","Long","Dark","Best Of","Bright","Guitar","Vocal","Keys","Drums"};for(int i=0;i<9;++i){auto&b=tags[size_t(i)];addAndMakeVisible(b);b.setButtonText(names[i]);b.setClickingTogglesState(true);b.onClick=[this,i]{for(int j=0;j<9;++j)if(j!=i)tags[size_t(j)].setToggleState(false,juce::dontSendNotification);refresh();};}
  for(auto*b:{&favOnly,&star,&save,&rename,&remove})addAndMakeVisible(b);favOnly.setClickingTogglesState(true);favOnly.onClick=[this]{refresh();};star.onClick=[this]{auto key=selectedKey();if(key.isNotEmpty()){library.toggleFavourite(key);refresh();}};
  addAndMakeVisible(name);name.setTextToShowWhenEmpty("Preset name / Save As",juce::Colour(0xff888888));save.onClick=[this]{auto key=library.saveUser(name.getText(),p.state.copyState());if(key.isNotEmpty()){p.state.state.setProperty("preset_key",key,nullptr);p.state.state.setProperty("preset_name",name.getText().trim(),nullptr);search.clear();category.setSelectedId(1,juce::dontSendNotification);for(auto&b:tags)b.setToggleState(false,juce::dontSendNotification);favOnly.setToggleState(false,juce::dontSendNotification);refresh();selectKey(key);onChange();}else refresh();};
  rename.onClick=[this]{auto key=selectedKey();if(library.renameUser(key,name.getText())){if(p.state.state.getProperty("preset_key").toString()==key)p.state.state.setProperty("preset_name",name.getText().trim(),nullptr);refresh();selectKey(key);onChange();}};
  remove.onClick=[this]{auto key=selectedKey();if(library.deleteUser(key)){refresh();name.clear();onChange();}};
  addAndMakeVisible(list);list.setModel(this);list.setRowHeight(30);list.setColour(juce::ListBox::backgroundColourId,juce::Colour(0xff161616));list.setOutlineThickness(1);list.setColour(juce::ListBox::outlineColourId,juce::Colour(0xff444444));list.getViewport()->setScrollBarsShown(true,false);
  for(auto*e:{&search,&name}){e->setColour(juce::TextEditor::backgroundColourId,juce::Colour(0xff151515));e->setColour(juce::TextEditor::textColourId,juce::Colour(0xffeeeeee));e->setColour(juce::TextEditor::outlineColourId,juce::Colour(0xff444444));}
  refresh();setSize(390,700);
 }
 ~PresetBrowser()override{list.setModel(nullptr);setLookAndFeel(nullptr);}
 void paint(juce::Graphics&g)override{g.fillAll(juce::Colour(0xff303030));g.setColour(juce::Colour(0xffdddddd));g.setFont(juce::Font(juce::FontOptions(12,juce::Font::bold)));g.drawText("TAGS",12,52,75,22,juce::Justification::centredLeft);g.setColour(juce::Colour(0xffaaaaaa));g.setFont(juce::Font(juce::FontOptions(11)));g.drawText(library.error.isNotEmpty()?library.error:juce::String(filtered.size())+" presets | "+juce::String(platebank::count)+" factory",12,getHeight()-24,getWidth()-24,20,juce::Justification::centredLeft);}
 void resized()override{int w=getWidth();search.setBounds(10,8,w-20,35);favOnly.setBounds(w-130,51,120,24);for(int i=0;i<9;++i)tags[size_t(i)].setBounds(12+(i%3)*(w-24)/3,82+(i/3)*32,(w-30)/3,27);category.setBounds(12,183,w-24,26);name.setBounds(12,218,w-62,28);star.setBounds(w-44,218,32,28);remove.setBounds(12,254,(w-32)/3,28);rename.setBounds(16+(w-32)/3,254,(w-32)/3,28);save.setBounds(20+2*(w-32)/3,254,(w-32)/3,28);list.setBounds(10,292,w-20,getHeight()-322);}
 void refresh(){juce::ScopedValueSetter<bool> guard(refreshing,true);auto key=p.state.state.getProperty("preset_key").toString();filtered.clear();auto query=search.getText().trim();juce::String tag;for(auto&b:tags)if(b.getToggleState())tag=b.getButtonText();for(int i=0;i<library.entries.size();++i){auto&e=library.entries.getReference(i);if(category.getSelectedId()>1&&e.category!=category.getText())continue;if(query.isNotEmpty()&&!(e.name+" "+e.category+" "+e.tags.joinIntoString(" ")).containsIgnoreCase(query))continue;if((favOnly.getToggleState()||tag=="Best Of")&&!library.favourites.contains(e.key))continue;auto mapped=tag=="Guitar"?"Guitarras":tag=="Vocal"?"Vocais":tag=="Keys"?"Teclas":tag=="Drums"?"Bateria":tag;if(mapped.isNotEmpty()&&mapped!="Best Of"&&!e.tags.contains(mapped))continue;filtered.add(i);}list.updateContent();list.deselectAllRows();selectKey(key);updateActions();repaint();}
private:
 PlateProcessor&p;std::function<void()>onChange;juce::LookAndFeel_V4 dark;PresetLibrary library;juce::TextEditor search,name;juce::ComboBox category;std::array<juce::TextButton,9>tags;juce::TextButton favOnly{"FAVORITES"},star{juce::String::charToString(0x2606)},save{"SAVE AS"},rename{"RENAME"},remove{"DELETE"};juce::ListBox list;juce::Array<int>filtered;bool refreshing=false;
 int getNumRows()override{return filtered.size();}
 juce::String selectedKey()const {int row=list.getSelectedRow();return juce::isPositiveAndBelow(row,filtered.size())?library.entries[filtered[row]].key:juce::String{};}
 void selectKey(const juce::String&key){for(int i=0;i<filtered.size();++i)if(library.entries[filtered[i]].key==key){list.selectRow(i);return;}}
 void updateActions(){auto key=selectedKey();bool user=key.startsWith("user:");rename.setEnabled(user);remove.setEnabled(user);star.setEnabled(key.isNotEmpty());star.setButtonText(juce::String::charToString(library.favourites.contains(key)?0x2605:0x2606));}
 void selectedRowsChanged(int row)override{if(juce::isPositiveAndBelow(row,filtered.size())){auto entry=library.entries[filtered[row]];name.setText(entry.name,false);if(!refreshing&&!juce::ModifierKeys::getCurrentModifiersRealtime().isAnyMouseButtonDown()){library.apply(entry,p);onChange();}}updateActions();}
 void paintListBoxItem(int row,juce::Graphics&g,int width,int height,bool selected)override{if(!juce::isPositiveAndBelow(row,filtered.size()))return;auto&e=library.entries.getReference(filtered[row]);if(selected)g.fillAll(juce::Colour(0xff514b36));g.setFont(juce::Font(juce::FontOptions(12,juce::Font::bold)));g.setColour(juce::Colour(0xffdddddd));g.drawText(e.name,10,0,width-110,height,juce::Justification::centredLeft);bool aux=float(e.state.getChildWithProperty("id","wet_solo").getProperty("value",1))>.5f;g.setColour(aux?juce::Colour(0xff9acace):juce::Colour(0xffe4c47b));g.setFont(juce::Font(juce::FontOptions(9,juce::Font::bold)));g.drawText(aux?"AUX":"INSERT",width-102,0,63,height,juce::Justification::centred);g.setColour(juce::Colour(0xffc4ae6c));g.drawText(juce::String::charToString(library.favourites.contains(e.key)?0x2605:0x2606),width-32,0,25,height,juce::Justification::centred);}
 void listBoxItemClicked(int row,const juce::MouseEvent&e)override{if(!juce::isPositiveAndBelow(row,filtered.size()))return;auto entry=library.entries[filtered[row]];if(e.x>=list.getWidth()-38){library.toggleFavourite(entry.key);refresh();return;}library.apply(entry,p);onChange();updateActions();}
 void returnKeyPressed(int row)override{if(juce::isPositiveAndBelow(row,filtered.size())){library.apply(library.entries[filtered[row]],p);onChange();}}
};
class PresetWindow:public juce::DocumentWindow {
public:
 PresetWindow(PlateProcessor&p,std::function<void()>changed):DocumentWindow("EMT 140 PLATE PRESETS",juce::Colour(0xff363636),DocumentWindow::closeButton){setUsingNativeTitleBar(false);setTitleBarHeight(30);setContentOwned(new PresetBrowser(p,std::move(changed)),true);setResizable(true,false);setResizeLimits(350,500,650,1000);}
 void closeButtonPressed()override{setVisible(false);}
 void refresh(){if(auto*b=dynamic_cast<PresetBrowser*>(getContentComponent()))b->refresh();}
};
